"""Verified additions from the user's lower-volume Physics textbook, printed pages 179-322."""
ITEMS=[]
def add(number,section,page,prompt,solution,steps,answer=None,options=None,figure=None,issues=None):
 ITEMS.append(dict(number=number,lesson=section,printed_page=page,prompt=prompt,solution=solution,explanation=steps,choice_answer=answer,options=options,figure=figure,issues=issues or []))

def choice(number,section,page,question,options,answer,steps,figure=None):
 prompt=question+'\n\n'+'\n\n'.join('**'+chr(65+i)+'.** '+s for i,s in enumerate(options))
 add(number,section,page,prompt,'正确答案：**'+answer+'**。\n\n'+options[ord(answer)-65],steps,answer,options,figure)

